            Paragraph(Text("For every assignment compatible with the stated prefix whose original F1/F2 score is below scale, the response requires an assignment still below scale with strictly smaller finite lexicographic rank.")),
            Node("raw-cut-14336", "raw_cut_14336", "Original suffix at depth 13, code 108728, node 371142",
                "The statement is EJMOriginalReplayAssembly.Accepted at depth 13, code 108728 and original node 371142. Its checker retains remaining fuel 8, the full prefixCache and full prefixPartial. The proof transports the concrete memoized checker equation through check_eq_original at exactly this fuel, index, cache and partial assignment. Decoder memoization supplies equality; the concrete suffix check remains a separate premise of the transport.", DescribeRole.Theorem),
            Node("raw-cut-14463", "raw_cut_14463", "Original suffix at depth 13, code 108858, node 373291",
                "The statement is EJMOriginalReplayAssembly.Accepted at depth 13, code 108858 and original node 373291. Its checker retains remaining fuel 8, the full prefixCache and full prefixPartial. The proof transports the concrete memoized checker equation through check_eq_original at exactly this fuel, index, cache and partial assignment. Decoder memoization supplies equality; the concrete suffix check remains a separate premise of the transport.", DescribeRole.Theorem),
            Node("response-cut-14336", "response_cut_14336", "Canonical response for cut 14336",
                "The complete row has depth 13, base-four code 108728, original node 371142, kind 2, reserved field 0, 621 subtree occurrences and completion domain 16384. For every assignment compatible with the stated prefix whose original F1/F2 score is below scale, the response requires an assignment still below scale with strictly smaller finite lexicographic rank. The proof invokes response_of_raw with the matching raw_cut acceptance and concrete depth/index side conditions.", DescribeRole.Theorem),
            Node("response-cut-14463", "response_cut_14463", "Canonical response for cut 14463",
